package net.civeira.phylax.features.document.theme.domain.valueobject;

import org.junit.jupiter.api.Assertions;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;

import net.civeira.phylax.common.exception.ConstraintException;

class CustomCssVOUnitTest {

  /**
   * @autogenerated ValueObjectGenerator
   */
  @Test
  @DisplayName("Test value object contruction for property custom css of theme ")
  void test_custom_css_v_o_builder() {
    Assertions.assertFalse(CustomCssVO.nullValue().getCustomCss().isPresent(),
        "A empty vo should have a null value");
    Assertions.assertFalse(CustomCssVO.tryFrom(null).getCustomCss().isPresent(),
        "With a null value, no present result");
    Assertions.assertEquals("one", CustomCssVO.from("one").getCustomCss().orElse(null));
    Object falingInstance = new Object() {};
    Assertions.assertThrows(ConstraintException.class, () -> CustomCssVO.tryFrom(falingInstance));
    Assertions.assertEquals("[" + "one" + "]", CustomCssVO.from("one").toString());
  }
}
